import type { Context } from "hono"
import type { SSEStreamingApi } from "hono/streaming"

import consola from "consola"
import { streamSSE } from "hono/streaming"

/**
 * Narrow a service result to its non-streaming form.
 *
 * Streaming services return an async iterable; non-streaming ones return a
 * plain response object. Test the property that actually defines the
 * distinction rather than a proxy for it: an earlier version checked for an own
 * `choices` property, which happened to work only because the iterator returned
 * by `events()` does not expose one (see POTENTIAL_FEATURES.md #3).
 */
export function isNonStreaming<T>(
  response: T,
): response is Exclude<T, AsyncIterable<unknown>> {
  return !(Symbol.asyncIterator in Object(response))
}

interface StreamSSEOptions {
  /** Request signal; an abort on it means the client went away. */
  signal?: AbortSignal
  /** Label used when logging a client disconnect. */
  label: string
}

/**
 * Wrap an SSE producer so that a client disconnect ends the stream quietly.
 *
 * A disconnect shows up either as an already-aborted request signal or as an
 * `AbortError` thrown while the upstream stream is being consumed. Neither is a
 * failure worth surfacing, so the stream simply ends. Anything else is
 * rethrown.
 *
 * This is the single definition of what "the client went away" means; it
 * previously existed as five structurally identical copies across the two route
 * handlers.
 */
export function streamSSEWithAbort(
  c: Context,
  { signal, label }: StreamSSEOptions,
  produce: (stream: SSEStreamingApi) => Promise<void>,
): Response {
  return streamSSE(c, async (stream) => {
    try {
      await produce(stream)
    } catch (error) {
      if (isClientAbort(error, signal)) {
        consola.debug(`${label} stream aborted by client`)
        return
      }
      throw error
    }
  })
}

/**
 * Whether an error ending a stream means the client went away.
 *
 * Exported because this predicate is the only real logic in this module, and
 * it is not observable through a route: swallowing and rethrowing produce the
 * same client-visible result (headers are already sent, so both end as HTTP
 * 200 with a partial body and a clean EOF). It therefore has to be tested
 * directly.
 */
export function isClientAbort(error: unknown, signal?: AbortSignal): boolean {
  return (
    signal?.aborted === true
    || (error instanceof Error && error.name === "AbortError")
  )
}

import type { Context } from "hono"

import consola from "consola"
import { type SSEMessage } from "hono/streaming"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { isNonStreaming, streamSSEWithAbort } from "~/lib/streaming"
import { getTokenCount } from "~/lib/tokenizer"
import { isNullish } from "~/lib/utils"
import {
  createChatCompletions,
  type ChatCompletionsPayload,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  let payload = await c.req.json<ChatCompletionsPayload>()
  consola.debug("Request payload:", JSON.stringify(payload).slice(-400))

  // Find the selected model
  const selectedModel = state.models?.data.find(
    (model) => model.id === payload.model,
  )

  // Calculate and display token count
  try {
    if (selectedModel) {
      const tokenCount = await getTokenCount(payload, selectedModel)
      consola.info("Current token count:", tokenCount)
    } else {
      consola.warn("No model selected, skipping token count calculation")
    }
  } catch (error) {
    consola.warn("Failed to calculate token count:", error)
  }

  if (state.manualApprove) await awaitApproval()

  if (isNullish(payload.max_tokens)) {
    payload = {
      ...payload,
      max_tokens: selectedModel?.capabilities.limits.max_output_tokens,
    }
    consola.debug("Set max_tokens to:", JSON.stringify(payload.max_tokens))
  }

  const endpoint = resolveEndpoint(payload.model, state.models)
  const signal = c.req.raw.signal

  // Route to /responses for GPT-5.x and models that only support it
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for model: ${payload.model}`)
    return handleResponsesEndpoint(c, payload, signal)
  }

  payload.reasoning_effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
  })

  // Existing /chat/completions path
  const response = await createChatCompletions(payload, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming response:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming response")
  return streamSSEWithAbort(
    c,
    { signal, label: "chat-completions" },
    async (stream) => {
      for await (const chunk of response) {
        consola.debug("Streaming chunk:", JSON.stringify(chunk))
        await stream.writeSSE(chunk as SSEMessage)
      }
    },
  )
}

async function handleResponsesEndpoint(
  c: Context,
  payload: ChatCompletionsPayload,
  signal?: AbortSignal,
) {
  const effort = resolveEffort({
    modelId: payload.model,
    requested: payload.reasoning_effort,
    cachedModels: state.models,
    defaultEffort: "medium",
  })
  const response = await createResponses(payload, effort, signal)

  if (isNonStreaming(response)) {
    consola.debug("Non-streaming /responses result:", JSON.stringify(response))
    return c.json(response)
  }

  consola.debug("Streaming /responses response")
  return streamSSEWithAbort(
    c,
    { signal, label: "/responses" },
    async (stream) => {
      const streamState = createResponsesStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          streamState,
        )

        for (const chunk of chunks) {
          consola.debug("Translated /responses chunk:", JSON.stringify(chunk))
          await stream.writeSSE({
            data: JSON.stringify(chunk),
          })
        }
      }
    },
  )
}

import type { CopilotUsage } from "~/lib/copilot-usage"
import type { RequestedEffort } from "~/lib/effort"

// Anthropic API Types

export interface AnthropicMessagesPayload {
  model: string
  messages: Array<AnthropicMessage>
  max_tokens: number
  system?: string | Array<AnthropicTextBlock>
  metadata?: {
    user_id?: string
  }
  stop_sequences?: Array<string>
  stream?: boolean
  temperature?: number
  top_p?: number
  top_k?: number
  tools?: Array<AnthropicTool>
  tool_choice?: {
    type: "auto" | "any" | "tool" | "none"
    name?: string
  }
  thinking?: {
    type: "enabled" | "disabled" | "adaptive"
    budget_tokens?: number
  }
  service_tier?: "auto" | "standard_only"
  output_config?: {
    effort?: RequestedEffort
    [key: string]: unknown
  }
}

export interface AnthropicTextBlock {
  type: "text"
  text: string
}

export interface AnthropicImageBlock {
  type: "image"
  source: {
    type: "base64"
    media_type: "image/jpeg" | "image/png" | "image/gif" | "image/webp"
    data: string
  }
}

export interface AnthropicToolResultBlock {
  type: "tool_result"
  tool_use_id: string
  content: string
  is_error?: boolean
}

export interface AnthropicToolUseBlock {
  type: "tool_use"
  id: string
  name: string
  input: Record<string, unknown>
}

export interface AnthropicThinkingBlock {
  type: "thinking"
  thinking: string
}

export type AnthropicUserContentBlock =
  | AnthropicTextBlock
  | AnthropicImageBlock
  | AnthropicToolResultBlock

export type AnthropicAssistantContentBlock =
  | AnthropicTextBlock
  | AnthropicToolUseBlock
  | AnthropicThinkingBlock

export interface AnthropicUserMessage {
  role: "user"
  content: string | Array<AnthropicUserContentBlock>
}

export interface AnthropicAssistantMessage {
  role: "assistant"
  content: string | Array<AnthropicAssistantContentBlock>
}

export type AnthropicMessage = AnthropicUserMessage | AnthropicAssistantMessage

export interface AnthropicTool {
  name: string
  description?: string
  input_schema: Record<string, unknown>
}

export interface AnthropicResponse {
  id: string
  type: "message"
  role: "assistant"
  content: Array<AnthropicAssistantContentBlock>
  model: string
  stop_reason:
    | "end_turn"
    | "max_tokens"
    | "stop_sequence"
    | "tool_use"
    | "pause_turn"
    | "refusal"
    | null
  stop_sequence: string | null
  copilot_usage?: CopilotUsage
  usage: {
    input_tokens: number
    output_tokens: number
    cache_creation_input_tokens?: number
    cache_read_input_tokens?: number
    service_tier?: "standard" | "priority" | "batch"
  }
}

export type AnthropicResponseContentBlock = AnthropicAssistantContentBlock

// Anthropic Stream Event Types
export interface AnthropicMessageStartEvent {
  type: "message_start"
  message: Omit<
    AnthropicResponse,
    "content" | "stop_reason" | "stop_sequence"
  > & {
    content: []
    stop_reason: null
    stop_sequence: null
  }
}

export interface AnthropicContentBlockStartEvent {
  type: "content_block_start"
  index: number
  content_block:
    | { type: "text"; text: string }
    | (Omit<AnthropicToolUseBlock, "input"> & {
        input: Record<string, unknown>
      })
    | { type: "thinking"; thinking: string }
}

export interface AnthropicContentBlockDeltaEvent {
  type: "content_block_delta"
  index: number
  delta:
    | { type: "text_delta"; text: string }
    | { type: "input_json_delta"; partial_json: string }
    | { type: "thinking_delta"; thinking: string }
    | { type: "signature_delta"; signature: string }
}

export interface AnthropicContentBlockStopEvent {
  type: "content_block_stop"
  index: number
}

export interface AnthropicMessageDeltaEvent {
  type: "message_delta"
  delta: {
    stop_reason?: AnthropicResponse["stop_reason"]
    stop_sequence?: string | null
  }
  usage?: {
    input_tokens?: number
    output_tokens: number
    cache_creation_input_tokens?: number
    cache_read_input_tokens?: number
  }
}

export interface AnthropicMessageStopEvent {
  type: "message_stop"
}

export interface AnthropicPingEvent {
  type: "ping"
}

export interface AnthropicErrorEvent {
  type: "error"
  error: {
    type: string
    message: string
  }
}

export type AnthropicStreamEventData =
  | AnthropicMessageStartEvent
  | AnthropicContentBlockStartEvent
  | AnthropicContentBlockDeltaEvent
  | AnthropicContentBlockStopEvent
  | AnthropicMessageDeltaEvent
  | AnthropicMessageStopEvent
  | AnthropicPingEvent
  | AnthropicErrorEvent

// State for streaming translation
export interface AnthropicStreamState {
  messageStartSent: boolean
  contentBlockIndex: number
  contentBlockOpen: boolean
  toolCalls: {
    [openAIToolIndex: number]: {
      id: string
      name: string
      anthropicBlockIndex: number
    }
  }
}

/** Fresh per-stream translation state. Mirrors createResponsesStreamState. */
export function createAnthropicStreamState(): AnthropicStreamState {
  return {
    messageStartSent: false,
    contentBlockIndex: 0,
    contentBlockOpen: false,
    toolCalls: {},
  }
}

import type { Context } from "hono"

import consola from "consola"

import { awaitApproval } from "~/lib/approval"
import { resolveEffort } from "~/lib/effort"
import { resolveEndpoint } from "~/lib/endpoint-routing"
import { anthropicToCopilotModelId } from "~/lib/model-mapping"
import { checkRateLimit } from "~/lib/rate-limit"
import { state } from "~/lib/state"
import { isNonStreaming, streamSSEWithAbort } from "~/lib/streaming"
import {
  createChatCompletions,
  type ChatCompletionChunk,
} from "~/services/copilot/create-chat-completions"
import {
  createResponses,
  createResponsesStreamState,
  translateResponsesStreamEvent,
} from "~/services/copilot/create-responses"
import {
  forwardNativeMessagesNonStreaming,
  forwardNativeMessagesStreaming,
} from "~/services/copilot/forward-native-messages"

import {
  createAnthropicStreamState,
  type AnthropicMessagesPayload,
} from "./anthropic-types"
import {
  translateToAnthropic,
  translateToOpenAI,
} from "./non-stream-translation"
import { translateChunkToAnthropicEvents } from "./stream-translation"

const CONTEXT_1M_BETA = "context-1m-2025-08-07"

/**
 * Check if the request wants 1M context via the anthropic-beta header.
 * The Claude Agent SDK sets `anthropic-beta: context-1m-2025-08-07`
 * instead of appending [1m] to the model name.
 */
function detectWants1M(c: Context): boolean {
  const betaHeader = c.req.header("anthropic-beta") ?? ""
  return betaHeader.split(",").some((s) => s.trim() === CONTEXT_1M_BETA)
}

export async function handleCompletion(c: Context) {
  await checkRateLimit(state)

  const anthropicPayload = await c.req.json<AnthropicMessagesPayload>()
  consola.debug("Anthropic request payload:", JSON.stringify(anthropicPayload))

  if (state.manualApprove) {
    await awaitApproval()
  }

  // Check per-request 1M context: anthropic-beta header or global flag
  const wants1M = detectWants1M(c) || state.is1MContext

  const copilotModelId = anthropicToCopilotModelId(
    anthropicPayload.model,
    wants1M,
  )
  const endpoint = resolveEndpoint(copilotModelId, state.models)
  const signal = c.req.raw.signal

  // Native Anthropic passthrough for Claude models
  if (endpoint === "/v1/messages") {
    consola.debug(`Using native /v1/messages passthrough for ${copilotModelId}`)
    return handleNativePassthrough(c, anthropicPayload, wants1M, signal)
  }

  // Translate Anthropic → OpenAI format for non-Claude models
  const openAIPayload = translateToOpenAI(anthropicPayload)
  consola.debug(
    "Translated OpenAI request payload:",
    JSON.stringify(openAIPayload),
  )

  // /responses for GPT-5.x models (responses-only or preferred)
  if (endpoint === "/responses") {
    consola.debug(`Using /responses endpoint for ${copilotModelId}`)
    const effort = resolveEffort({
      modelId: copilotModelId,
      requested: anthropicPayload.output_config?.effort,
      cachedModels: state.models,
      defaultEffort: "medium",
    })
    return handleResponsesViaAnthropic({
      context: c,
      openAIPayload,
      effort,
      signal,
    })
  }

  // /chat/completions for legacy models
  openAIPayload.reasoning_effort = resolveEffort({
    modelId: copilotModelId,
    requested: anthropicPayload.output_config?.effort,
    cachedModels: state.models,
  })
  const response = await createChatCompletions(openAIPayload, signal)

  if (isNonStreaming(response)) {
    consola.debug(
      "Non-streaming response from Copilot:",
      JSON.stringify(response).slice(-400),
    )
    const anthropicResponse = translateToAnthropic(response)
    consola.debug(
      "Translated Anthropic response:",
      JSON.stringify(anthropicResponse),
    )
    return c.json(anthropicResponse)
  }

  consola.debug("Streaming response from Copilot")
  return streamSSEWithAbort(
    c,
    { signal, label: "/v1/messages chat-completions" },
    async (stream) => {
      const streamState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        consola.debug("Copilot raw stream event:", JSON.stringify(rawEvent))
        if (rawEvent.data === "[DONE]") {
          break
        }

        if (!rawEvent.data) {
          continue
        }

        const chunk = JSON.parse(rawEvent.data) as ChatCompletionChunk
        const events = translateChunkToAnthropicEvents(chunk, streamState)

        for (const event of events) {
          consola.debug("Translated Anthropic event:", JSON.stringify(event))
          await stream.writeSSE({
            event: event.type,
            data: JSON.stringify(event),
          })
        }
      }
    },
  )
}

// eslint-disable-next-line max-params
async function handleNativePassthrough(
  c: Context,
  payload: AnthropicMessagesPayload,
  is1M: boolean,
  signal?: AbortSignal,
) {
  if (!payload.stream) {
    const response = await forwardNativeMessagesNonStreaming(
      payload,
      is1M,
      signal,
    )
    return c.json(response)
  }

  return streamSSEWithAbort(
    c,
    { signal, label: "/v1/messages native passthrough" },
    async (stream) => {
      for await (const event of forwardNativeMessagesStreaming(
        payload,
        is1M,
        signal,
      )) {
        await stream.writeSSE({
          event: event.type,
          data: JSON.stringify(event.data),
        })
      }
    },
  )
}

/**
 * Handle a request that needs the /responses endpoint but arrived via /v1/messages.
 * Flow: Anthropic payload → already translated to OpenAI → /responses → OpenAI response → Anthropic format.
 */
interface ResponsesViaAnthropicOptions {
  context: Context
  openAIPayload: Parameters<typeof createResponses>[0]
  effort?: string
  signal?: AbortSignal
}

async function handleResponsesViaAnthropic({
  context,
  openAIPayload,
  effort,
  signal,
}: ResponsesViaAnthropicOptions) {
  const response = await createResponses(openAIPayload, effort, signal)

  if (isNonStreaming(response)) {
    const anthropicResponse = translateToAnthropic(response)
    return context.json(anthropicResponse)
  }

  return streamSSEWithAbort(
    context,
    { signal, label: "/v1/messages /responses" },
    async (stream) => {
      const responsesState = createResponsesStreamState()
      const anthropicState = createAnthropicStreamState()

      for await (const rawEvent of response) {
        if (!rawEvent.data || rawEvent.data === "[DONE]") continue

        const parsed = JSON.parse(rawEvent.data) as Record<string, unknown>
        const eventType =
          rawEvent.event ?? (parsed.type as string | undefined) ?? ""

        const chunks = translateResponsesStreamEvent(
          { event: eventType, data: parsed },
          responsesState,
        )

        for (const chunk of chunks) {
          const events = translateChunkToAnthropicEvents(chunk, anthropicState)
          for (const event of events) {
            await stream.writeSSE({
              event: event.type,
              data: JSON.stringify(event),
            })
          }
        }
      }
    },
  )
}

/**
 * Client-visible behaviour of the streaming handlers when a stream ends early.
 *
 * NOTE ON WHAT THESE DO AND DO NOT PROVE. By the time a stream fails, the
 * response headers are already sent, so a swallowed abort and a rethrown error
 * look identical from outside: HTTP 200, a partial body, and a clean EOF. A
 * mutation forcing isClientAbort to return false leaves every test in this file
 * passing. So these pin the *client-visible* contract only; the swallow-versus-
 * rethrow decision is pinned directly in tests/streaming-helpers.test.ts.
 *
 * They are still worth having: they exercise all five streaming paths across
 * both handlers end to end, which is what made the consolidation of five
 * duplicated catch blocks into src/lib/streaming.ts verifiable as
 * behaviour-preserving.
 */
import { afterEach, beforeEach, describe, expect, it, mock } from "bun:test"

import type { ModelsResponse } from "~/services/copilot/get-models"

import { state } from "~/lib/state"
import { server } from "~/server"

const originalFetch = globalThis.fetch
const originalModels = state.models
const originalToken = state.copilotToken
const originalManualApprove = state.manualApprove

function model(id: string, endpoints: Array<string>) {
  return {
    id,
    name: id,
    object: "model",
    vendor: id.startsWith("claude-") ? "anthropic" : "openai",
    version: "1",
    preview: false,
    model_picker_enabled: true,
    supported_endpoints: endpoints,
    capabilities: {
      family: id,
      limits: { max_output_tokens: 64000 },
      object: "model_capabilities",
      supports: { tool_calls: true },
      tokenizer: "o200k_base",
      type: "chat",
    },
  }
}

const catalog = {
  object: "list",
  data: [
    model("claude-sonnet-5", ["/v1/messages", "/chat/completions"]),
    model("gpt-5.5", ["/responses", "/chat/completions"]),
    model("gpt-4.1", ["/chat/completions"]),
  ],
} as unknown as ModelsResponse

/**
 * An SSE response that yields one usable event and then throws an AbortError
 * mid-iteration, mimicking a client disconnect during streaming.
 */
function abortingStream(firstEvent: string): Response {
  const encoder = new TextEncoder()
  let sent = false
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (!sent) {
        sent = true
        controller.enqueue(encoder.encode(`${firstEvent}\n\n`))
        return
      }
      const abortError = new Error("The operation was aborted")
      abortError.name = "AbortError"
      controller.error(abortError)
    },
  })
  return new Response(body, {
    headers: { "content-type": "text/event-stream" },
  })
}

/** An SSE response that fails mid-iteration for a reason that is NOT an abort. */
function failingStream(firstEvent: string): Response {
  const encoder = new TextEncoder()
  let sent = false
  const body = new ReadableStream<Uint8Array>({
    pull(controller) {
      if (!sent) {
        sent = true
        controller.enqueue(encoder.encode(`${firstEvent}\n\n`))
        return
      }
      controller.error(new Error("upstream exploded"))
    },
  })
  return new Response(body, {
    headers: { "content-type": "text/event-stream" },
  })
}

function mockFetch(body: () => Response) {
  globalThis.fetch = mock(() =>
    Promise.resolve(body()),
  ) as unknown as typeof fetch
}

function postMessages(body: unknown) {
  return server.request("/v1/messages", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  })
}

function postChat(body: unknown) {
  return server.request("/v1/chat/completions", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  })
}

beforeEach(() => {
  state.copilotToken = "test-token"
  state.models = catalog
  state.manualApprove = false
})

afterEach(() => {
  globalThis.fetch = originalFetch
  state.models = originalModels
  state.copilotToken = originalToken
  state.manualApprove = originalManualApprove
})

const anthropicStart = `event: message_start\ndata: {"type":"message_start","message":{"id":"msg_1","role":"assistant","content":[],"model":"claude-sonnet-5"}}`
const responsesStart = `event: response.created\ndata: {"type":"response.created","response":{"id":"resp_1","model":"gpt-5.5"}}`
const chunkStart = `data: {"id":"c1","object":"chat.completion.chunk","created":1,"model":"gpt-4.1","choices":[{"index":0,"delta":{"role":"assistant","content":"hi"},"finish_reason":null}]}`

describe("streaming abort is swallowed, not surfaced as an error", () => {
  it("/v1/messages native passthrough ends cleanly on AbortError", async () => {
    mockFetch(() => abortingStream(anthropicStart))

    const response = await postMessages({
      model: "claude-sonnet-5",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    expect(response.status).toBe(200)
    // Consuming the body must not reject: the handler returns instead of
    // rethrowing, so the stream simply ends after what was already emitted.
    const body = await response.text()
    expect(body).toContain("message_start")
  })

  it("/v1/messages /responses tier ends cleanly on AbortError", async () => {
    mockFetch(() => abortingStream(responsesStart))

    const response = await postMessages({
      model: "gpt-5.5",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    expect(response.status).toBe(200)
    expect(await response.text()).toBeString()
  })

  it("/v1/messages chat-completions tier ends cleanly on AbortError", async () => {
    mockFetch(() => abortingStream(chunkStart))

    const response = await postMessages({
      model: "gpt-4.1",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    expect(response.status).toBe(200)
    expect(await response.text()).toBeString()
  })

  it("/v1/chat/completions passthrough tier ends cleanly on AbortError", async () => {
    mockFetch(() => abortingStream(chunkStart))

    const response = await postChat({
      model: "gpt-4.1",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    expect(response.status).toBe(200)
    expect(await response.text()).toBeString()
  })

  it("/v1/chat/completions /responses tier ends cleanly on AbortError", async () => {
    mockFetch(() => abortingStream(responsesStart))

    const response = await postChat({
      model: "gpt-5.5",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    expect(response.status).toBe(200)
    expect(await response.text()).toBeString()
  })

  it("CHARACTERIZATION: a non-abort failure truncates silently", async () => {
    mockFetch(() => failingStream(anthropicStart))

    const response = await postMessages({
      model: "claude-sonnet-5",
      max_tokens: 64,
      stream: true,
      messages: [{ role: "user", content: "hi" }],
    })

    const body = await response.text()

    // Pins today's behaviour, which is NOT obviously correct. The handler
    // rethrows non-abort errors, but headers are already sent, so the client
    // sees HTTP 200, a partial body, and a clean EOF. There is no message_stop
    // and no error event, so a truncated stream is indistinguishable from a
    // complete one and an Anthropic client waits for a terminator that never
    // arrives.
    //
    // The responses-stream-error-events feature solved the adjacent case -
    // errors the upstream *signals* in-band (response.failed / incomplete /
    // error) - but a transport-level failure mid-stream is still unhandled.
    // src/routes/messages/stream-translation.ts already exports
    // translateErrorToAnthropicErrorEvent, so the machinery exists; it is
    // simply not wired to these catch blocks.
    expect(response.status).toBe(200)
    expect(body).toContain("message_start")
    expect(body).not.toContain("message_stop")
    expect(body).not.toContain('"type":"error"')
  })
})

/**
 * Unit coverage for src/lib/streaming.ts.
 *
 * These exist because the route-level tests in
 * tests/streaming-abort-handling.test.ts cannot distinguish a swallowed abort
 * from a rethrown one: by the time either happens the response headers are
 * already sent, so both end as HTTP 200 with a partial body and a clean EOF.
 * A mutation that forced isClientAbort to return false left every one of those
 * route tests passing. The logic therefore has to be pinned here, directly.
 */
import { describe, expect, it } from "bun:test"

import { isClientAbort, isNonStreaming } from "~/lib/streaming"

async function* oneValue() {
  yield await Promise.resolve(1)
}

describe("isClientAbort", () => {
  it("is true when the request signal is already aborted", () => {
    const controller = new AbortController()
    controller.abort()
    expect(isClientAbort(new Error("anything"), controller.signal)).toBe(true)
  })

  it("is true for an AbortError even without a signal", () => {
    const error = new Error("The operation was aborted")
    error.name = "AbortError"
    expect(isClientAbort(error)).toBe(true)
  })

  it("is false for an ordinary error on a live signal", () => {
    const controller = new AbortController()
    expect(
      isClientAbort(new Error("upstream exploded"), controller.signal),
    ).toBe(false)
  })

  it("is false for an ordinary error with no signal", () => {
    expect(isClientAbort(new Error("upstream exploded"))).toBe(false)
  })

  it("is false for a non-Error thrown value", () => {
    expect(isClientAbort("just a string")).toBe(false)
    expect(isClientAbort(undefined)).toBe(false)
  })
})

describe("isNonStreaming", () => {
  it("treats a plain response object as non-streaming", () => {
    expect(isNonStreaming({ id: "c1", choices: [] })).toBe(true)
  })

  it("treats an async generator as streaming", () => {
    expect(isNonStreaming(oneValue())).toBe(false)
  })

  it("treats any async iterable as streaming, even without a choices field", () => {
    const iterable = { [Symbol.asyncIterator]: oneValue }
    expect(isNonStreaming(iterable)).toBe(false)
  })

  it("does not depend on a choices property", () => {
    // The previous implementation asked whether the value had an own `choices`
    // property, which only worked because the iterator returned by events()
    // happens not to expose one (POTENTIAL_FEATURES.md #3). An async iterable
    // that did carry `choices` would have been misclassified as non-streaming.
    const streamingWithChoices = {
      choices: [],
      [Symbol.asyncIterator]: oneValue,
    }
    expect(isNonStreaming(streamingWithChoices)).toBe(false)

    // And a plain object without `choices` is still non-streaming.
    expect(isNonStreaming({ id: "resp_1", output: [] })).toBe(true)
  })
})
